"""Extract strings only from .rodata (and .data.rel.ro etc) sections of an ELF."""
import sys, struct, re

def sections(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:4] != b'\x7fELF':
        sys.exit('not ELF')
    is64 = data[4] == 2
    endian = '<' if data[5] == 1 else '>'
    if is64:
        e_shoff, = struct.unpack_from(endian+'Q', data, 0x28)
        e_shentsize, e_shnum, e_shstrndx = struct.unpack_from(endian+'HHH', data, 0x3a)
        fmt = endian+'IIQQQQIIQQ'
    else:
        e_shoff, = struct.unpack_from(endian+'I', data, 0x20)
        e_shentsize, e_shnum, e_shstrndx = struct.unpack_from(endian+'HHH', data, 0x2e)
        fmt = endian+'IIIIIIIIII'
    secs = []
    for i in range(e_shnum):
        off = e_shoff + i*e_shentsize
        v = struct.unpack_from(fmt, data, off)
        secs.append(dict(name=v[0], typ=v[1], offset=v[4], size=v[5]))
    shstr = secs[e_shstrndx]
    out = []
    for s in secs:
        noff = shstr['offset']+s['name']
        end = data.find(b'\0', noff)
        nm = data[noff:end].decode(errors='replace')
        out.append((nm, s))
    return data, out

if __name__ == '__main__':
    minlen = 5
    args = [a for a in sys.argv[1:] if not a.startswith('-')]
    for a in sys.argv[1:]:
        if a.startswith('-n'): minlen = int(a[2:])
    data, secs = sections(args[0])
    pat = <访问令牌_01>'[\x20-\x7e]{%d,}' % minlen)
    pat16 = re.compile(rb'(?:[\x20-\x7e]\x00){%d,}' % minlen)
    for nm, s in secs:
        if nm in ('.rodata', '.data.rel.ro', '.data', '.rodata.str1.1', '.rodata.str1.8') or nm.startswith('.rodata'):
            blob = data[s['offset']:s['offset']+s['size']]
