        dec = AES.new(key, AES.MODE_ECB).decrypt(chunk)
        s = score(dec)
        print(f'ECB off={off} len={len(chunk)} score={s}/{len(dec)}', dec[:60] if s > len(dec)*0.7 else '')
# try CBC with IV = key, zero IV, iv=first16 of body at offsets
