            dec = AES.new(key, AES.MODE_CFB, iv=iv, segment_size=128).decrypt(chunk)
            s = score(dec)
            if len(dec) and s > len(dec)*0.7:
                print(f'CFB iv@{nonce_off} off={off} score={s}/{len(dec)}', dec[:80])
        except Exception:
            pass
# try CBC ciphertext stealing not supported; try ECB on body minus trailing bytes
for trail in range(0, 16):
    chunk = body[:len(body)-trail] if trail else body
    if len(chunk) >= 16 and len(chunk) % 16 == 0:
